// Generates a location registry (~230 zips) for Phase 2's Collector demo,
// scaled to the "run for 200-300 zips" target. Each of the 78 anchor
// cities (scripts/us-cities.mjs) contributes its known-real anchor zip plus
// 2 nearby zips generated by incrementing the numeric zip — USPS assigns
// contiguous zip blocks per city, so e.g. Chicago's 60601 having neighbors
// at 60602/60603 is a real pattern, but these two per city are NOT
// individually verified against USPS data the way the anchor zip is.
// Labeled clearly here and in the DB seed — don't treat as ground truth.

import fs from "node:fs";
import path from "node:path";
import { CITIES } from "./us-cities.mjs";

const OUT_DIR = path.join(process.cwd(), "data", "samples");
fs.mkdirSync(OUT_DIR, { recursive: true });

const EXTRA_ZIPS_PER_CITY = 3;

function incrementZip(zip, delta) {
  const num = parseInt(zip, 10) + delta;
  return String(num).padStart(5, "0");
}

const rows = [];
for (const [city, zip, state] of CITIES) {
  rows.push({ zip, city, state, confidenceNote: "anchor" });
  for (let i = 1; i <= EXTRA_ZIPS_PER_CITY; i++) {
    rows.push({ zip: incrementZip(zip, i), city, state, confidenceNote: "approximate_same_metro" });
  }
}

const header = "zip,city,state,confidenceNote";
const lines = rows.map((r) => [r.zip, r.city, r.state, r.confidenceNote].join(","));
fs.writeFileSync(path.join(OUT_DIR, "locations.csv"), [header, ...lines].join("\n") + "\n");

console.log(`Wrote ${rows.length} location rows (${CITIES.length} anchors x ${1 + EXTRA_ZIPS_PER_CITY}) to ${OUT_DIR}/locations.csv`);
